"use client";

import { useEffect, useRef, useState } from "react";

export function SiteMusic() {
  const audioRef = useRef<HTMLAudioElement>(null);

  const [playing, setPlaying] = useState(false);

  useEffect(() => {
    const audio = audioRef.current;

    if (!audio) return;

    audio.volume = 0.35;
  }, []);

  const toggleMusic = async () => {
    const audio = audioRef.current;

    if (!audio) return;

    if (audio.paused) {
      try {
        await audio.play();
        setPlaying(true);
      } catch (error) {
        console.error("Music could not play:", error);
      }
    } else {
      audio.pause();
      setPlaying(false);
    }
  };

  return (
    <>
      <audio
        ref={audioRef}
        src="/audio/salon-alain.mp3"
        loop
        preload="metadata"
      />

      <button
        type="button"
        onClick={toggleMusic}
        aria-label={playing ? "Pause background music" : "Play background music"}
        className="
          fixed
          bottom-5
          left-5
          z-[100]
          flex
          h-12
          w-12
          items-center
          justify-center
          rounded-full
          border
          border-plum-300/70
          bg-white/85
          text-plum-700
          shadow-[0_8px_30px_rgba(40,20,35,0.15)]
          backdrop-blur-md
          transition-all
          duration-300
          hover:-translate-y-1
          hover:bg-plum-700
          hover:text-white

          sm:bottom-7
          sm:left-7
          sm:h-14
          sm:w-14
        "
      >
        {playing ? (
          <svg
            viewBox="0 0 24 24"
            className="h-5 w-5"
            fill="currentColor"
            aria-hidden="true"
          >
            <path d="M7 5h4v14H7V5Zm6 0h4v14h-4V5Z" />
          </svg>
        ) : (
          <svg
            viewBox="0 0 24 24"
            className="h-6 w-6"
            fill="currentColor"
            aria-hidden="true"
          >
            <path d="M9 18V5l10-2v13.5a3.5 3.5 0 1 1-2-3.16V7.42l-6 1.2V16.5A3.5 3.5 0 1 1 9 18Z" />
          </svg>
        )}

        <span
          className="
            pointer-events-none
            absolute
            left-full
            ml-3
            hidden
            whitespace-nowrap
            rounded-full
            bg-ink
            px-3
            py-2
            text-xs
            text-white
            opacity-0
            transition-opacity
            duration-300
            group-hover:opacity-100
            sm:block
          "
        >
          {playing ? "Pause music" : "Play music"}
        </span>
      </button>
    </>
  );
}
